    expect(cfg).toEqual({
      matrix: { os: ["ubuntu-latest"], node: [18, 20] },
      include: [{ os: "ubuntu-latest", node: 18, lint: true }],
      exclude: [{ node: 20 }],
      maxParallel: 3,
